import{S as t,o as n,c as h,a9 as e,B as l}from"./chunks/framework.DxG24V0C.js";const p="/agentsrc/images/opencode/codex-04-hero.png",k="/agentsrc/images/opencode/codex-04-loop.png",r="/agentsrc/images/opencode/codex-04-inject.png",d="/agentsrc/images/opencode/codex-04-vs.png",y=JSON.parse('{"title":"Compact 系统：3 种压缩机制","description":"","frontmatter":{},"headers":[],"relativePath":"codex/04-compact.md","filePath":"codex/04-compact.md","lastUpdated":1786085271000}'),E={name:"codex/04-compact.md"},F=Object.assign(E,{setup(o){const i=[{question:"Codex 选择哪种压缩实现时，核心判断依据是什么？",options:["默认优先使用 Local 实现在本地由当前会话模型执行压缩","依据 provider 是否支持 remote 选择走远端还是本地压缩","根据当前上下文历史长度自动匹配对应压缩实现策略","用户在启动时通过命令行参数或配置文件手动指定压缩方式"],correct:1,explanation:"先判断 provider 是否支持 remote compaction（OpenAI 官方 provider 支持），支持再检查 Feature::RemoteCompactionV2 是否开启决定走 V2 还是 V1，都不满足则 fallback 到 Local。Ollama/LM Studio 这类本地 provider 走 Local。"},{question:"InitialContextInjection 枚举的两种策略（BeforeLastUserMessage vs DoNotInject）分别对应什么场景？",options:["BeforeLastUserMessage 用于 pre-turn DoNotInject 用于 manual","BeforeLastUserMessage 用于 mid-turn DoNotInject 用于 pre-turn","两策略之间不存在本质差异仅命名约定不同","DoNotInject 用作默认适用于全部压缩触发时机"],correct:1,explanation:"Mid-turn 场景下模型正在工具循环中，压缩后必须继续 sampling，如果不注入初始上下文模型会丢失 developer instructions 等关键信息。Pre-turn/manual 场景压缩完整个 turn 结束，下次 turn 自然走 record_context_updates 全量注入。"},{question:"Local compact 实现中，当 compact 自身也超过 context window 时，Codex 做了什么处理？",options:["抛出上下文超限错误并终止当前压缩任务执行流程","移除历史中最旧的消息后重试以保留近期关键对话内容","自动降级切换到 remote compact 实现绕过本地窗口限制","降低摘要内容精度标准来缩减单次压缩所需 token 数量"],correct:1,explanation:'砍掉 history.items[0]（最早的那条记录）再重试。这样会破坏 prefix cache，但目的是"保新不保旧"——保留最近的对话和 compact prompt，让生成的摘要质量更高。'},{question:"Claude Code 的 5 级压缩与 Codex 的 3 种 LLM 调用压缩，两种设计哲学的根本差异是什么？",options:["Codex 压缩质量更高而 CC 压缩执行速度更快整体延迟更低","CC 采用成本优先前四级仅操作数据结构而 Codex 采用质量优先","CC 压缩层级更多功能覆盖面更广因此设计上优于 Codex 方案","两套压缩体系在底层原理和实现效果上没有任何本质区别"],correct:1,explanation:"CC 的哲学是优先用便宜操作（数据结构变换）省空间，只有迫不得已才调 LLM，大多数会话走不到第 5 级。Codex 的哲学是任何压缩都涉及 LLM 保证质量，通过选择本地/远程 LLM 来优化成本。CC 策略对长会话更经济，Codex 策略对短会话更简单直接。"}];return(c,s)=>{const a=t("Quiz");return n(),h("div",null,[s[0]||(s[0]=e("",114)),l(a,{questions:i})])}}});export{y as __pageData,F as default};
